package edu.klh.soa.productlot; import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import java.util.*; @RestController @RequestMapping("/lots") public class LotController {private final LotRepository repo;public LotController(LotRepository r){repo=r;} @GetMapping public List<ProductLot> all(){return repo.findAll();} @GetMapping("/{lot}") public ProductLot one(@PathVariable String lot){return repo.findByLotCode(lot).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"lot not found"));} @PostMapping public ResponseEntity<ProductLot> add(@RequestBody ProductLot p){if(p.lotCode==null||p.productCode==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"productCode and lotCode required");return ResponseEntity.status(201).body(repo.save(p));} @PostMapping("/seed") public Map<String,Object> seed(){if(repo.count()==0){repo.save(new ProductLot("MED-100","LOT-A100","SUP-ALPHA"));repo.save(new ProductLot("MED-100","LOT-A101","SUP-BETA"));repo.save(new ProductLot("MED-200","LOT-B200","SUP-GAMMA"));}return Map.of("seeded",true,"count",repo.count());}}